// src/pages/OtherProfile.js

import { useState } from "react";

import {
  useLocation,
  useNavigate,
} from "react-router-dom";

import { FiSettings } from "react-icons/fi";

function OtherProfile() {
  const navigate = useNavigate();
  const location = useLocation();

  const userName =
    location.state?.user || "민지";

  const [isFollowing, setIsFollowing] =
    useState(false);

  const userData = {
    민지: {
      followers: 23,
      following: 15,

      books: [
        {
          title: "노르웨이의 숲",
          review:
            "상실 이후에도 사람은 계속 살아간다는 점이 가장 인상 깊었다.",
        },

        {
          title: "데미안",
          review:
            "자기 자신을 찾아가는 과정이 정말 인상 깊었다.",
        },

        {
          title: "어린왕자",
          review:
            "순수함에 대해 다시 생각하게 만든 책이었다.",
        },
      ],
    },

    현우: {
      followers: 31,
      following: 20,

      books: [
        {
          title: "1984",
          review:
            "감시 사회의 무서움을 현실적으로 보여줬다.",
        },

        {
          title: "데미안",
          review:
            "성장이란 결국 자신을 마주하는 과정이었다.",
        },
      ],
    },

    서연: {
      followers: 18,
      following: 9,

      books: [
        {
          title: "채식주의자",
          review:
            "강렬하면서도 오래 기억에 남는 작품이었다.",
        },

        {
          title: "해변의 카프카",
          review:
            "현실과 환상이 섞인 분위기가 좋았다.",
        },
      ],
    },
  };

  const profile =
    userData[userName] ||
    userData["민지"];

  return (
    <div className="page">
      {/* 상단 */}

      <div className="profile-header">
        <div className="logo">
          READLY
        </div>

        <FiSettings className="setting-icon" />
      </div>

      {/* 프로필 */}

      <div className="profile-top">
        <div className="profile-image"></div>

        <div className="profile-info">
          <div className="profile-name">
            {userName}
          </div>

          <div className="follow-wrap">
            <div className="follow-box">
              <div className="follow-num">
                {profile.followers}
              </div>

              <div className="follow-text">
                팔로워
              </div>
            </div>

            <div className="follow-box">
              <div className="follow-num">
                {profile.following}
              </div>

              <div className="follow-text">
                팔로잉
              </div>
            </div>
          </div>

          <button
            className={
              isFollowing
                ? "following-btn"
                : "follow-btn"
            }
            onClick={() =>
              setIsFollowing(
                !isFollowing
              )
            }
          >
            {isFollowing
              ? "팔로잉"
              : "팔로우"}
          </button>
        </div>
      </div>

      {/* 소개 */}

      <div className="profile-desc">
        함께 책 읽고 이야기하는 걸
        좋아해요 📖
      </div>

      <div className="line"></div>

      {/* 책장 */}

      <div className="books-section">
        <div className="stack-message">
          {userName}님은
          <br />
          현재 4.2cm 쌓았어요!
        </div>

        <div className="book-stack-wrap">
          <div className="shelf-top"></div>

          {profile.books.map(
            (book, index) => (
              <div
                key={index}
                className="book-item"
                style={{
                  cursor: "pointer",
                }}
                onClick={() =>
                  navigate("/review", {
                    state: {
                      title:
                        book.title,
                      review:
                        book.review,
                    },
                  })
                }
              >
                {book.title}
              </div>
            )
          )}

          <div className="shelf"></div>
        </div>
      </div>
    </div>
  );
}

export default OtherProfile;
